// Fail closed. If a caller forgets a field we deny rather than guess.
return $input.all().map((item) => {
  const raw = item.json.payload
    ? (typeof item.json.payload === 'string' ? JSON.parse(item.json.payload) : item.json.payload)
    : (item.json.rails_request || item.json);
  const request = {
    channel: raw.channel || '',
    purpose: raw.purpose || '',
    contact_email: String(raw.contact_email || '').trim().toLowerCase(),
    contact_phone: String(raw.contact_phone || '').replace(/[^0-9]/g, '').slice(-10),
    contact_handle: String(raw.contact_handle || '').trim().toLowerCase(),
    inbound_message: raw.inbound_message || '',
    consent: raw.consent || { basis: null, recorded_at: null },
    estimated_cost_usd: Number(raw.estimated_cost_usd || 0),
    workflow: raw.workflow || 'unknown'
  };
  const identifier = request.contact_email || request.contact_phone || request.contact_handle;
  const malformed = !request.channel || !request.purpose;
  return { json: { request, identifier, malformed } };
});

