function deny(code, reason) {
  return $input.all().map((item) => ({ json: {
    allowed: false, code, reason,
    request: item.json.rails_request || item.json.request || null,
    decided_at: new Date().toISOString()
  } }));
}
return deny('kill_switch', 'Kill switch is on, or the rails request was malformed.');

// Source of truth: logic/optout.js (unit tested in tests/optout.test.js).
// Precedence is fixed: suppression > inbound opt-out > lawful basis.
const OPT_OUT_KEYWORDS = [
  'stop', 'stopall', 'unsubscribe', 'opt out', 'optout', 'opt-out',
  'remove me', 'take me off', 'do not contact', 'dnc', 'cancel', 'quit', 'end'
];
const FALSE_POSITIVE_PHRASES = ['stop by', 'stop in', 'non stop', 'nonstop', 'one stop', 'stop light',
  'cancel my other', 'end of the month', 'end of month', 'weekend', 'quit my job', 'front end', 'back end'];
function normalize(t) {
  return String(t || '').toLowerCase().replace(/[^a-z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim();
}
function isOptOut(text) {
  let msg = normalize(text);
  if (!msg) return false;
  for (const p of FALSE_POSITIVE_PHRASES) { if (msg.includes(p)) msg = normalize(msg.split(p).join(' ')); }
  if (!msg) return false;
  const words = msg.split(' ');
  for (const kw of OPT_OUT_KEYWORDS) {
    if (msg === kw) return true;
    if (kw.includes(' ') && msg.includes(kw)) return true;
    if (words.length <= 4 && words.includes(kw)) return true;
  }
  return false;
}
const req = $('Normalize Rails Input').first().json.request;
return $input.all().map((item) => {
  const row = item.json || {};
  const basis = row.consent_basis || (req.consent && req.consent.basis) || null;
  const recorded = row.consent_recorded_at || (req.consent && req.consent.recorded_at) || null;
  const validBasis = ['consent', 'contract', 'legitimate_interest'].includes(basis) && Boolean(recorded);
  let code = 'allow';
  let reason = 'No suppression, opt-out or consent block.';
  if (row.suppressed === true) { code = 'suppressed'; reason = 'Contact is on the suppression list.'; }
  else if (isOptOut(req.inbound_message)) { code = 'opt_out_request'; reason = 'Inbound message is an opt-out request.'; }
  else if (!validBasis) { code = 'no_lawful_basis'; reason = 'No recorded lawful basis for contact.'; }
  return { json: { allowed: code === 'allow', code, reason, request: req } };
});

return $input.all().map((item) => ({ json: {
  allowed: false,
  code: item.json.code || 'no_lawful_basis',
  reason: item.json.reason || 'Consent or suppression check failed.',
  request: item.json.request || null,
  decided_at: new Date().toISOString()
} }));

// Per-channel hourly cap and a global daily cap. Both are env-configurable and
// both default to numbers a real agency can live with, not to Infinity.
const PER_CHANNEL_HOUR = Number($env.RAILS_CHANNEL_PER_HOUR || 30);
const GLOBAL_DAY = Number($env.RAILS_GLOBAL_PER_DAY || 500);
const req = $('Opt Out And Consent Check').first().json.request;
return $input.all().map((item) => {
  const hour = Number(item.json.channel_last_hour || 0);
  const day = Number(item.json.all_last_day || 0);
  const withinHour = hour < PER_CHANNEL_HOUR;
  const withinDay = day < GLOBAL_DAY;
  return { json: {
    allowed: withinHour && withinDay,
    code: withinHour && withinDay ? 'allow' : 'rate_limited',
    reason: withinHour && withinDay
      ? 'Within rate limits.'
      : 'Rate limit hit: ' + hour + '/' + PER_CHANNEL_HOUR + ' this hour on ' + req.channel + ', ' + day + '/' + GLOBAL_DAY + ' today.',
    request: req,
    counters: { channel_last_hour: hour, all_last_day: day }
  } };
});

function deny(code, reason) {
  return $input.all().map((item) => ({ json: {
    allowed: false, code, reason,
    request: item.json.rails_request || item.json.request || null,
    decided_at: new Date().toISOString()
  } }));
}
return deny('rate_limited', 'Rate limit exceeded for this channel or for the day.');

