// Daily spend cap across every paid call the pack makes (enrichment, signals,
// messaging). The estimated cost of THIS action is included before the check.
const CAP = Number($env.RAILS_DAILY_SPEND_CAP_USD || 25);
const req = $('Rate Limit Check').first().json.request;
return $input.all().map((item) => {
  const spent = Number(item.json.spent_today || 0);
  const projected = spent + Number(req.estimated_cost_usd || 0);
  const ok = projected <= CAP;
  return { json: {
    allowed: ok,
    code: ok ? 'allow' : 'spend_cap',
    reason: ok ? 'Within daily spend cap.' : 'Daily spend cap reached: ' + projected.toFixed(2) + ' of ' + CAP.toFixed(2) + ' USD.',
    request: req,
    spend: { spent_today: spent, projected }
  } };
});

function deny(code, reason) {
  return $input.all().map((item) => ({ json: {
    allowed: false, code, reason,
    request: item.json.rails_request || item.json.request || null,
    decided_at: new Date().toISOString()
  } }));
}
return deny('spend_cap', 'Daily spend cap reached.');

return $input.all().map((item) => ({ json: {
